export type ServerEvent =
  | {
      type: "connected";
      data: {
        projectId: string;
      };
    }
  | {
      type: "heartbeat";
      data: {
        timestamp: string;
      };
    }
  | {
      type: "changed";
      data: {
        source: ServerEventSourceEnum;
        version?: string;
      };
    }
  | {
      type: "workspace-error";
      data: {
        code: string;
        message: string;
      };
    };

export interface HealthResponse {
  status: "ok";
  stage: HealthResponseStageEnum;
  contractVersion: 1;
}

export interface ContextResponse {
  capabilities?: string[];
  project: string;
  /** Стабильный идентификатор пути конфигурации проекта */
  projectId: string;
  configPath: string;
  storagePath: string;
  /** Автор изменений, заданный при запуске сервера */
  actor: string;
  config: {
    version: 1;
    /** @default "local" */
    mode: "local";
    projectId?: string;
    projectSettings?: {
      /**
       * Отображаемое имя проекта, от 1 до 120 символов без переносов строк
       * @minLength 1
       * @maxLength 120
       * @pattern ^[^\p{Cc}]+$
       */
      name: string;
      /**
       * Slug адреса: 2–64 строчные латинские буквы/цифры с одиночными дефисами между частями
       * @minLength 2
       * @maxLength 64
       * @pattern ^[a-z0-9]+(?:-[a-z0-9]+)*$
       */
      slug: string;
      /**
       * Разделы библиотеки в порядке отображения; пустой список допустим
       * @maxItems 100
       */
      documentSections?: {
        /**
         * Постоянный ID раздела библиотеки
         * @pattern ^[a-zA-Z0-9_-]{1,64}$
         */
        id: string;
        /**
         * Название раздела библиотеки
         * @minLength 1
         */
        name: string;
      }[];
      /**
       * Ревизия настроек проекта для защиты от одновременного редактирования
       * @min 0
       * @max 9007199254740991
       */
      revision: number;
      version: 1 | 2 | 3;
      /**
       * Читаемый ключ сущности; назначается ядром, может иметь прежние алиасы
       * @minLength 1
       * @maxLength 128
       * @pattern ^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)*$
       */
      entityKey?: string;
      aliases?: string[];
      events?: {
        /**
         * @exclusiveMin 0
         * @max 9007199254740991
         */
        revision: number;
        /**
         * Автор операции
         * @maxLength 128
         */
        actor: string;
        /**
         * Момент времени в UTC
         * @format date-time
         * @pattern ^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z))$
         */
        at: string;
        action: string;
      }[];
      requests?: Partial<
        Record<
          string,
          {
            hash: string;
            result: {
              id: string;
              key: string;
              /**
               * @min 0
               * @max 9007199254740991
               */
              revision: number;
            };
          }
        >
      >;
    };
    /** @minLength 1 */
    storageDir: string;
    /** @minLength 1 */
    defaultStatus: string;
    /** @minItems 1 */
    readyStatuses: string[];
    statuses: Partial<
      Record<
        string,
        {
          /** @default false */
          terminal: boolean;
          /** @default false */
          satisfiesDependencies: boolean;
          color?: ContextResponseColorEnum;
        }
      >
    >;
    mcp?: {
      /**
       * @min 0
       * @max 65535
       * @default 4710
       */
      port: number;
    };
    /** @default {"port":4700} */
    server: {
      /**
       * @min 0
       * @max 65535
       * @default 4700
       */
      port: number;
      /** @format uri */
      url?: string;
    };
    /** @default {"format":"text","defaultLimit":20,"maxBytes":16384} */
    output: {
      /** @default "text" */
      format: ContextResponseFormatEnum;
      /**
       * @min 1
       * @max 100
       * @default 20
       */
      defaultLimit: number;
      /**
       * @min 1024
       * @max 134217728
       * @default 16384
       */
      maxBytes: number;
    };
  };
}

